def jq_value_type(v):
    if v is None:
        return "null"
    elif isinstance(v, bool):
        return "boolean"
    elif isinstance(v, JqNumber):
        return "number"
    elif isinstance(v, str):
        return "string"
    elif isinstance(v, list):
        return "array"
    elif isinstance(v, dict):
        return "object"
    else:
        return "unknown"

def jq_type_order(v):
    t = jq_value_type(v)
    if t == "null":
        return 0
    elif t == "boolean":
        return 1
    elif t == "number":
        return 2
    elif t == "string":
        return 3
    elif t == "array":
        return 4
    elif t == "object":
        return 5
    return 6

def jq_number_cmp(a, b):
    # return -1,0,1 ; nan smallest, -inf, finite, inf
    # a,b are JqNumber
