        return 0
    if a_nan:
        return -1
    if b_nan:
        return 1
    # check inf via float conversion
    af = a.to_float()
    bf = b.to_float()
    a_inf = math.isinf(af)
    b_inf = math.isinf(bf)
    if a_inf and b_inf:
        if af == bf:
            return 0
        elif af < bf:
            return -1
        else:
            return 1
    if a_inf:
        return 1 if af > 0 else -1  # +inf largest, -inf smallest (but nan smaller, already handled)
        # Actually need to compare -inf vs finite: -inf < finite
        # +inf > finite
    if b_inf:
        return -1 if bf > 0 else 1
    # both finite: if both dec, compare as Decimal
    if a.is_dec and b.is_dec:
        if a.dec == b.dec:
            return 0
        elif a.dec < b.dec:
            return -1
        else:
            return 1
    else:
        # at least one float finite: compare as floats
        if af == bf:
            return 0
        elif af < bf:
            return -1
        else:
            return 1

def jq_compare(a, b):
    oa = jq_type_order(a)
    ob = jq_type_order(b)
    if oa != ob:
        return -1 if oa < ob else 1
    # same type
    t = jq_value_type(a)
    if t == "null":
        return 0
    elif t == "boolean":
