        # So compare sorted items list
        ia = [(k, a[k]) for k in ka]
        ib = [(k, b[k]) for k in kb]
        for (ka1, va), (kb1, vb) in zip(ia, ib):
            if ka1 != kb1:
                return -1 if ka1 < kb1 else 1
            c = jq_compare(va, vb)
            if c != 0:
