            return False
        for k in a:
            if not jq_equal(a[k], b[k]):
                return False
        return True
    return False

def jq_less(a, b):
    # for < operator: need total order, but nan handling: nan < nan true (per probing), not 0.
    # Our jq_compare returns 0 for nan==nan, but < should be true. So special case.
    ta = jq_value_type(a)
    tb = jq_value_type(b)
    oa = jq_type_order(a)
    ob = jq_type_order(b)
    if oa != ob:
        return oa < ob
    # same type
    if ta == "number":
        if a.is_nan() and b.is_nan():
            return True  # nan < nan true
        if a.is_nan():
            # nan < anything (within numbers) true, except? nan vs nan already, nan vs others true
            return True
        if b.is_nan():
            # finite/inf < nan? false (since nan smallest)
            return False
        return jq_number_cmp(a, b) < 0
    else:
        return jq_compare(a, b) < 0

def jq_greater(a, b):
    ta = jq_value_type(a)
    tb = jq_value_type(b)
    oa = jq_type_order(a)
    ob = jq_type_order(b)
    if oa != ob:
        return oa > ob
    if ta == "number":
        if a.is_nan() or b.is_nan():
            # nan > anything false, anything > nan true? Check: 1 > nan true, nan > 1 false, nan>nan false
            if a.is_nan():
                return False
            if b.is_nan():
                return True
        return jq_number_cmp(a, b) > 0
    else:
        return jq_compare(a, b) > 0

def jq_le(a,b):
    return jq_less(a,b) or jq_equal(a,b)
def jq_ge(a,b):
    return jq_greater(a,b) or jq_equal(a,b)

def deepcopy_jq(v):
    if isinstance(v, JqNumber):
        if v.is_dec:
            return JqNumber(dec=v.dec)
        else:
            return JqNumber(flt=v.flt)
    elif isinstance(v, list):
        return [deepcopy_jq(x) for x in v]
    elif isinstance(v, dict):
        return {k: deepcopy_jq(val) for k,val in v.items()}
    else:
        return v

