class JqNumber:
    __slots__ = ('dec', 'flt', 'is_dec')
    def __init__(self, dec=None, flt=None):
        if dec is not None:
            self.dec = dec
            self.flt = None
            self.is_dec = True
        else:
            self.dec = None
            self.flt = flt
            self.is_dec = False
    @staticmethod
    def from_decimal(d):
        return JqNumber(dec=d)
    @staticmethod
    def from_float(f):
        return JqNumber(flt=float(f))
    @staticmethod
    def from_int(i):
        return JqNumber(dec=Decimal(i))
    def is_nan(self):
        if self.is_dec:
            return False
        else:
            return math.isnan(self.flt)
    def is_inf(self):
        if self.is_dec:
            try:
                f = float(self.dec)
            except:
                return True
            return math.isinf(f)
        else:
            return math.isinf(self.flt)
    def to_float(self):
        if self.is_dec:
            # Decimal -0 -> +0.0
            if self.dec.is_zero():
                return 0.0
            try:
                f = float(self.dec)
            except:
                # overflow? Decimal too large -> inf with sign
                if self.dec.is_signed():
                    return float('-inf')
                else:
                    return float('inf')
            # float() already gives inf for huge, ok
            if f == 0.0:
                return 0.0
            return f
        else:
            return self.flt
    def __repr__(self):
        if self.is_dec:
            return f"JqNumber(dec={self.dec})"
        else:
            return f"JqNumber(flt={self.flt})"

def format_float(f):
    if math.isnan(f):
        return "null"
    if math.isinf(f):
        if f > 0:
            return DBL_MAX_STR
        else:
            return DBL_MAX_NEG_STR
    # handle -0.0? repr(-0.0) = '-0.0' -> '-0' ; repr(0.0)='0.0' -> '0'
    s = repr(f)
    # Python repr for 1e15 gives '1000000000000000.0' -> strip .0
    if s.endswith('.0'):
        # check if contains 'e' or 'E'? repr with .0 never has e? Actually 1e15 repr has .0 without e. Strip.
        s = s[:-2]
    return s

def jq_number_to_str(n):
    if n.is_dec:
        return str(n.dec)
    else:
        return format_float(n.flt)

def jq_value_type(v):
    if v is None:
        return "null"
    elif isinstance(v, bool):
        return "boolean"
    elif isinstance(v, JqNumber):
        return "number"
    elif isinstance(v, str):
        return "string"
    elif isinstance(v, list):
        return "array"
    elif isinstance(v, dict):
        return "object"
    else:
        return "unknown"

def jq_type_order(v):
    t = jq_value_type(v)
    if t == "null":
        return 0
    elif t == "boolean":
        return 1
    elif t == "number":
        return 2
    elif t == "string":
        return 3
    elif t == "array":
        return 4
    elif t == "object":
        return 5
    return 6

def jq_number_cmp(a, b):
    # return -1,0,1 ; nan smallest, -inf, finite, inf
    # a,b are JqNumber
    a_nan = a.is_nan()
    b_nan = b.is_nan()
    if a_nan and b_nan:
        return 0
    if a_nan:
        return -1
    if b_nan:
        return 1
    # check inf via float conversion
    af = a.to_float()
    bf = b.to_float()
    a_inf = math.isinf(af)
    b_inf = math.isinf(bf)
    if a_inf and b_inf:
        if af == bf:
            return 0
        elif af < bf:
            return -1
        else:
            return 1
    if a_inf:
        return 1 if af > 0 else -1  # +inf largest, -inf smallest (but nan smaller, already handled)
