        # +inf > finite
    if b_inf:
        return -1 if bf > 0 else 1
    # both finite: if both dec, compare as Decimal
    if a.is_dec and b.is_dec:
        if a.dec == b.dec:
            return 0
        elif a.dec < b.dec:
            return -1
        else:
            return 1
    else:
