        return -1 if len(ia) < len(ib) else 1
    return 0

def jq_equal(a, b):
    # numbers: use jq_number_cmp==0? But nan != nan, nan==nan false. Our cmp returns 0 for nan==nan, but equal should be false.
    ta = jq_value_type(a)
    tb = jq_value_type(b)
    if ta != tb:
        return False
    if ta == "null":
        return True
    if ta == "boolean":
        return a == b
    if ta == "number":
        if a.is_nan() or b.is_nan():
            return False
        return jq_number_cmp(a, b) == 0
    if ta == "string":
        return a == b
    if ta == "array":
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not jq_equal(x, y):
                return False
        return True
    if ta == "object":
        if set(a.keys()) != set(b.keys()):
            return False
        for k in a:
            if not jq_equal(a[k], b[k]):
                return False
        return True
    return False

def jq_less(a, b):
    # for < operator: need total order, but nan handling: nan < nan true (per probing), not 0.
    # Our jq_compare returns 0 for nan==nan, but < should be true. So special case.
    ta = jq_value_type(a)
    tb = jq_value_type(b)
    oa = jq_type_order(a)
    ob = jq_type_order(b)
    if oa != ob:
        return oa < ob
    # same type
    if ta == "number":
        if a.is_nan() and b.is_nan():
            return True  # nan < nan true
        if a.is_nan():
            # nan < anything (within numbers) true, except? nan vs nan already, nan vs others true
            return True
        if b.is_nan():
            # finite/inf < nan? false (since nan smallest)
            return False
        return jq_number_cmp(a, b) < 0
    else:
        return jq_compare(a, b) < 0

def jq_greater(a, b):
    ta = jq_value_type(a)
    tb = jq_value_type(b)
    oa = jq_type_order(a)
    ob = jq_type_order(b)
    if oa != ob:
        return oa > ob
    if ta == "number":
